var gladosLaunched = false;
function launchGLaDOS() {
    if (gladosLaunched) return;
    gladosLaunched = true;
    window.consolecontent = gladosBanner() + memGreeting();
    flushAchievements();
    jQuery(cssInject).appendTo(jQuery('head'));
    jQuery(bodyInject).appendTo(jQuery('body'));
    jQuery('img.one').prop('src', imgInject);
    document.removeEventListener('keydown', eggkeyHandler, false);

    // start egg
    jQuery(document).click(function () {
        jQuery("#e_eggwrapper #userinputworkaround").focus()
    });
    jQuery("#e_eggwrapper #userinputworkaround").focus();

    jQuery(window).on("keydown", function (e) {

        if (window.ctrlDown && e.keyCode == 67) {
            console.log('Ctrl+C interrupt');
            abort();
            sfxStop();
            audio1.pause();
            audio2.pause();
            audio3.pause();
            audio4.pause();
            audio5.pause();
            return;
        }
        if (window.consolerunning) {
            jQuery("#e_eggwrapper #userinputworkaround").val("");
            window.userinput = "";
            return;
        }
        setTimeout(function () {
            window.userinput = jQuery("#e_eggwrapper #userinputworkaround").val();
            if (e.which == 13) {
                e.preventDefault();
                e.stopPropagation();
                jQuery("#e_eggwrapper #userinputworkaround").val("");
                runCommand(window.userinput);
                // Achievements earned by instant commands show right after their output.
                if (!window.consolerunning) {
                    flushAchievements();
                }
            } else if (e.which == 38) {
                e.preventDefault();
                e.stopPropagation();
                oneCommandBack();
            } else if (e.which == 40) {
                e.preventDefault();
                e.stopPropagation();
                oneCommandForward();
            }
            updateConsole();
        }, 50);
    });
    var startdelay = true;
    setTimeout(function () {
        if (startdelay) {
            window.userinput = "";
            jQuery("#e_eggwrapper #userinputworkaround").val("");
            updateConsole();
            startdelay = false;
        }
    }, 200);
    updateConsole();
    audio1.play();
    // end egg  
}

var eggkeyHandler = function (event) {

    // If the key isn't in the pattern, or isn't the current key in the pattern, reset
    if (pattern.indexOf(event.key) < 0 || event.key !== pattern[current]) {
        current = 0;
        return;
    }
    console.log("Listening for Konami...");
    // Update how much of the pattern is complete
    current++;

    // If complete, run then stop listening
    if (pattern.length === current) {
        current = 0;
        launchGLaDOS();
    }
};


